function markupOnly() {
  return src.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[^>]*>[\s\S]*?<\/style>/g, ' ');
}
const CLICK_LISTENER = /document\s*\.\s*addEventListener\(\s*['"]click['"]/;
const BACKUP_TABLE = /^(?:public\.)?\w*_?backup\b/i;
